INSERT INTO AUD_GATE_WAITS (PIPELINE_RUN_ID,TASK_ID,WAIT_KIND,FIRST_CHECK_AT,NEXT_CHECK_AT,WAIT_UNTIL,LOOKS,EVENT_OBSERVATIONS) VALUES (:pipeline_run_id,:task_id,'EVENT',:first_check_at,:next_check_at,:wait_until,0,:observations) ON CONFLICT (PIPELINE_RUN_ID,(COALESCE(TASK_ID,0)),WAIT_KIND) DO UPDATE SET NEXT_CHECK_AT=excluded.NEXT_CHECK_AT, EVENT_OBSERVATIONS=excluded.EVENT_OBSERVATIONS
